## 6. 목업 API

_이 부분은 devServer.before 문법 변경으로 업데이트 예정이다._

````js
module.exports = {
  devServer: {
    before: app => {
      res.get("/api/users/", (req, res) => {
        res.json([
          { id: 1, name: "Alice" },
          { id: 2, name: "Bek" },
          { id: 3, name: "Chris" },
        ])
      }
    }
  }
}
````
{: file="webpack.config.js"}

