  if(age>=19){
    result = "여자 성인입니다.";
  } else {
    result = "여자 미성년자입니다.";
  }
}
document.write("당신은"+ result +"<br>");
````


### 다중 if~else

여러 조건을 체크해야 할 때 사용

````javascript
if(조건식-1){
  조건식-1의 결과가 참일 때 실행할 문장;
