````js
class HeaderComponent extends HTMLElement {
  connectedCallback() {
    this.innerHTML = `
      <header>
        <nav>
          <a href="#" id="home-link">Home</a>
          <a href="#" id="about-link">About</a>
          <a href="/contact">Contact</a>
