````javascript
(store.js)

import { createStore } from "vuex";

const store = createStore({
  state () {
    return {
      likes: 36,
    }
  },
  mutations: {
    changeLikes(state, data){
      const isLikes = data[0];
      const idx = data[1];
      state.likes[idx] += (isLikes) ? 1 : -1;
