### @응용

게시물 등록 시 Likes 배열을 추가해보자

````javascript
(store.js)

import { createStore } from "vuex";

const store = createStore({
  state () {
    return {
      likes: [ 36, 0, 5 ],
      isLikes: [false, false, false],
    }
  },
  mutations: {
    changeLikes(state, data){
      state.likes[data] += (state.isLikes[data]) ? -1 : 1;
      state.isLikes[data] = !state.isLikes[data]
    },
    LikesItemShift(state){
      state.likes.unshift(0);
      state.isLikes.unshift(false);
    }
  }
})

export default store;
````

````vue
(App.vue)

<template>
  <div class="header">
    <h1 class="logo"><a href="#" title="vue-stagram"></a></h1>
    <div class="header-button-left">
      <a href="#" v-if="tab==1 || tab==2" @click="tab=0">Cancel</a>
    </div>
    <div class="header-button-right">
      <a href="#" v-if="tab==1" @click="tab=2">Next</a>
      <a href="#" v-if="tab==2" @click="publish">Write</a>
    </div>
  </div>

  <Container :post="post" :tab="tab" :SelectFilter="SelectFilter" :uploadImage="uploadImage" @write=" n => uploadText = n " />
  <button @click="more();" type="button" class="btn_more" v-if="tab==0">더보기</button>

  <div class="footer">
    <div class="file_wrap" v-if="tab==0">
      <input type="file" id="file" class="inputfile" accept="image/*" multiple @change="upload">
      <label for="file" class="input-plus" title="이미지 업로드"></label>
    </div>
  </div>

</template>

<script>
import post from './assets/data.js'
import Container from './components/Container.vue'
import axios from 'axios'

export default {
  name:'App',
  data(){
    return {
      post : post,
      get: 0,
      tab: 0,
      uploadImage: '',
      uploadText: '',
      SelectFilter: '',
    }
  },
  methods: {
    publish(){
      const newPost = {
        name: "aluvy",
        userImage: "./img/profile1.jpg",
        postImage: this.uploadImage,
        likes: 0,
        date: "May 15",
        liked: false,
        content: this.uploadText,
        filter: this.SelectFilter,
      };
      this.post.unshift(newPost);
      this.tab = 0;
      this.$store.commit('LikesItemShift');
    },
    upload(e){
      const file = e.target.files;  // 업로드한 파일이 담겨있음
      const type = "image";

      if( file[0].type.indexOf(type) == -1 ){   // 문자열이 존재하지 않으면 -1 리턴
        alert("이미지만 업로드 해주세요.");
        return;
      }

      const url = URL.createObjectURL(file[0]); // 업로드한 파일의 임시 URL
      this.tab = 1;
      this.uploadImage = url;

    },
    more(){
      if( this.get > 1 ){

        const btn_more = document.querySelector(".btn_more");
        const p = document.createElement("p");
        p.innerText = "게시물이 없습니다.";
        p.classList.add("no_post");
        btn_more.after(p);
        btn_more.remove();

        return;
      }
      axios.get(`https://codingapple1.github.io/vue/more${this.get}.json`)
      .then( result => {
        this.post.push(result.data);
        this.get++;
      })
      .catch( error =>{
        // 요청 실패 시
        console.log(error);
      })
    }
  },
  components:{
    Container,
  },
  mounted(){
    this.emitter.on('FilterName', (a)=>{
      this.SelectFilter = a;
      console.log(this.SelectFilter);
    });
  }
}
</script>
````

Vuex에서는 state를 수정할 때 mutations 함수를 만들어서 수정하라고 배워봤는데,   
가끔 서버에서 데이터를 가져와서 수정하고 싶을 때가 있다.   
그럴때 당연히 서버로 ajax 요청을 날리면 되는데   
그런건 mutations에서 직접 하지 않고 actions라는 항목에 적어야 한다.

왜나하면 mutations 함수들을 만들 때 내부에 ajax처럼 오래걸리는 코드를 작성하면   
나중에 길게 코드짤 때 힘들어져서 그렇습니다.

````javascript
(store.js)
...
actions: {
	// ajax나 오래걸리는 작업
}
...
````

## 더보기 게시물 ajax 요청하기
시간이 소요되는 코드는 actions에 작성한다. (ex ajax)

### step
1. actions 함수 작성
2. mutation 함수 작성
3. $store.dispatch('actions 함수')
4. actions함수에서 mutation함수를 이용해 state 변경

### check 1
- mutation 함수 실행 : $store.commit('함수명', data)
- actions 함수 실행 : $store.dispatch('함수명')

### check 2
state 수정은 mutation에서 한다

````javascript
(store.js)

import { createStore } from "vuex"
import axios from 'axios'

const store = createStore({
  state () {
    return {
      likes: [ 36, 0, 5 ],
      isLikes: [false, false, false],
      more: [],
    }
  },
  mutations: {
    changeLikes(state, data){
      state.likes[data] += (state.isLikes[data]) ? -1 : 1;
      state.isLikes[data] = !state.isLikes[data]
    },
    LikesItemShift(state){
      state.likes.unshift(0);
      state.isLikes.unshift(false);
    },
    setMore(state, data){
      state.more.push(data);
    }
  },
  actions: {
    getData(context){
      axios.get(`https://codingapple1.github.io/vue/more0.json`)
      .then( result => {
        context.commit('setMore', result.data);   // axios로 가져온 데이터를 mutations setMore을 이용해 저장한다. (저장을 바로 할 수 없기 때문에 commit문을 씀)
      })
      .catch( error =>{
        console.log(error);
      })
    }
  }
})

export default store;
````

````vue
(App.vue)

<template>
  ...
  <p>{{ $store.state.more }}</p>
  <button @click="$store.dispatch('getData')" type="button" class="btn_more" v-if="tab==0">더보기</button>

</template>

...
````

## Compositon API
프로젝트가 커지고 코드가 길어지면 작업하기가 어려워지는데   
관련된 코드들을 찢어놓지 않고 개발하는 방법으로 composition API라는걸 제공한다.


### Options API
지금까지 했던 방법 : component에서 data()만들고 life cycle hook, components, computed 등 각 항목들을 신설해서 기능개발을 하는 방법을 options API라고 한다.   
(API : 사용방법)

Composition API를 사용하면 관련있는 코드를 한 곳에 모아놓을 수 있다.

````javascript
export default {
  name: 'MyPage',
  setup(){  // create life cycle hook과 비슷함
    // setup() 안에서
    // 데이터 생성, 조작
    // methods, computed, watch 생성
    // hook 걸기 등 가능
    // 거의 모든 기능개발을 setup 한 곳에서 가능
  },
````

### 문법
데이터는 ref() 함수 안에 담고, return {} 해줘야 사용이 가능하다.

````javascript
import { ref } from 'vue';
````

````javascript
// created life cycle hook과 비슷함
  setup(props, context){  // props:props / context: attrs, slots, emit등등
    let follower = ref([]);
    return { follower }
},
````

#### 예제1

````javascript
export default {
  name: 'MyPage',
  setup(){  // created life cycle hook과 비슷함

    let follower = ref([]);   // 데이터 (array, object가 아닌 데이터를 보관함)
    let test = reactive({});  // 데이터 (reactive한 변수를 만든다, 보통 array,object를 보관함)

    // mounted 후 ajax 요청함, import 필요 (on + lifecyclehook)
    onMounted(()=>{
      axios.get('./follower.json').then( data => {
        follower.value = data.data;   // 데이터를 수정하려면 데이터.value를 수정해야 함
      });
    });
    
    return { follower }
  },
}
````

### ref()
**referenct data type**   
데이터 변경시 실시간 재렌더링 가능한 이유는 reference data 때문임   
그래서 모든 데이터를 reference data type으로 감싸야 실시간 재 랜더링이 가능하다.

- `ref()` : 재렌더링 데이터, Array, Object가 아닌 나머지 데이터


### toRefs()
props를 setup()에서 사용할 때   
여러개의 항목들을 한번에 ref로 감싸고 싶을 때 toRefs()

````javascript
import { onMounted, reactive, toRefs } from 'vue';
````

````javascript
setup (props, context){  // props:props / context: attrs, slots, emit등등
  let { one, two } = toRefs(props); // 사용할 땐 one,value
  console.log(one.value);
},
props: {
	one: Number,
}
````

````html
<p>{{ one }}</p>
````

중괄호로 변수명 만드는 문법 = ES6 Destructuring 문법


## Composition API in watch()

````javascript
import { watch } from 'vue';
````

````javascript
setup(props){  // props:props / context: attrs, slots, emit등등
  let { one } = toRefs(props); // 사용할 땐 one,value
  watch(감시할데이터, ()=>{
    // 변경시 실행코드
  });
},
````


## Composition API in computed()

````javascript
import { computed } from 'vue';
````

````javascript
setup(){
  let follower = reactive([]);      // 데이터

  // mounted 후 ajax 요청함, import 필요 (on + lifecyclehook)
  onMounted(()=>{
    axios.get('./follower.json').then( data => {
    follower.value = data.data;   // 데이터를 수정하려면 데이터.value를 수정해야 함

    let result = computed(()=>{
      return follower.value.length;
    });
    console.log(result.value);

    });
  });

  return { follower }
},
````

