  // Set Swiper
  function setSwiperGnb(_plugin) {
    _plugin.slide = new Swiper(_plugin.$container, {
      a11y: true,
      loop: false,
      centeredSlides: false,
      slidesPerView: 'auto',
      freeMode: true,
      watchSlidesVisibility: true,
      keyboardControl: true,
      slidesOffsetBefore: 0,
      slidesOffsetAfter: 0,
      observer: true,
      observeParents: true,
      onInit: function (swiper) {
