    $('html').attr('lang') || 'en'; /* 210412 | 접근성 | 대체텍스트 추가 */
  var $shareBox = $('.md_share_box');
  var $shareDim = $('.md_share_dimd');
  var $shareCloseBtn = $('.md_btn_share_close');

  /* 210412 | 접근성 | 대체텍스트 추가 */
  $shareBox
    .find('a')
    .not($shareCloseBtn)
    .attr('title', langSet[lang]['openWindow']);
  $shareBox.find('.tit').text(langSet[lang].share.shareOpen).toString();
  $shareCloseBtn.find('span').text(langSet[lang].share.shareClose).toString();
  /* //210412 | 접근성 | 대체텍스트 추가 */

  var resizeTimer = new Timer(function () {
    mdShareClose();
  }, 100);

  // share dim
  $shareDim.click(function () {
    mdShareClose();
    return false;
  });

  // share close
  $shareCloseBtn.on({
    click: function () {
      mdShareClose();
      return false;
    },
    keydown: function (e) {
      if (e.keyCode == 9) {
        $shareBox.focus();
        return false;
      }
    },
  });

  $shareBox.on('focusin', function (e) {
    e.stopPropagation();
    e.preventDefault();
    setTimeout(function () {
      $('.md_btn_share.on').length &&
        $('.md_btn_share.on').addClass('isShareBoxTarget');
      $('.btn_md_share.on').length &&
        $('.btn_md_share.on').addClass('isShareBoxTarget');
      $('.add_share.on').length &&
        $('.add_share.on').addClass('isShareBoxTarget');
    }, 0);
  });

  // share box
  $shareBox.keydown(function (e) {
    e.stopPropagation();
    var isShift = window.event.shiftKey ? true : false;
    var $focusItems = $shareBox
      .parent()
      .find('a:visible, button:visible, [tabindex]');
    if ($focusItems.first().is($(e.target))) {
      if (e.keyCode == 9 && isShift) $focusItems.last().focus();
    }
    if ($focusItems.last().is($(e.target))) {
      if (e.keyCode == 9 && !isShift) $focusItems.first().focus();
    }
  });
  $(window).on({
    resize: function () {
      resizeTimer.start();
    },
    scroll: function () {
      resizeTimer.start();
    },
  });
});

function md_pop_share(obj) {
  if ($(obj).hasClass('on')) {
    $(obj).removeClass('on');
    $('.md_share_area').removeClass('on').removeClass('off');
    $('.md_btn_share').removeClass('on');
  } else {
    var offsetPosition = $(obj).offset();
    var w = ($(window).width() - $('#wrap').width()) * 0.5;
    var x = offsetPosition.left + 30 - w;
    var y = offsetPosition.top - 2;
    $('#md_share_area').addClass('on');
    $('#md_share_area').css('left', x).css('top', y);
    $('.md_share_box').attr('tabindex', 0);
    $('.md_share_box').focus();
    $('.md_btn_share').removeClass('on');
    $(obj).addClass('on');
  }
  return false;
}
