    $('.md_btn_share.on').length && $('.md_btn_share.on').removeClass('on');
    $('.btn_md_share.on').length && $('.btn_md_share.on').removeClass('on');
    $('.add_share.on').length && $('.add_share.on').removeClass('on');
    $('.isShareBoxTarget').length &&
